('81000000-0000-4000-8000-000000000002','controlled_on_road_fossil_diesel_medium_heavy_2007_2022','held_candidate','mobile-diesel-combustion','m74-development-v1','7598384902729e8a6708beb359e7564f500ad85c0d3ad38f094ee580a05c0497','1dc0bb7249d91e854004a8cadd34068be3fc03ecdd6e10b4cf297d375d7f52a6','416931c40b347f1e22e9d4019ca1c28bd27ce40d7c16a3beeac3dadbbb783187','c151f9b90b23eba7ee9d36dd57a851ecf7a6f200c915579819b683d2b3b3c1c7','["epa_hub_2025_xlsx","epa_hub_2025_pdf","epa_mobile_guidance_2023_pdf","ghg_protocol_required_gases_gwp_2013_pdf","ghg_protocol_corporate_standard_pdf"]','2025-01-01','2026-01-01','["domain_release_pending","rights_release_pending","runtime_release_prohibited"]','848883159be48c88a0dab8589ad371dcdbbf8dd07966a3d5fbcfd0799f7a530b'),
