import type { WorkspaceSql } from "./workspace"
import {
  M80_DATA_CLASSIFICATION,
  M80_FIXTURE_PROFILE,
  M80_FIXTURE_VERSION,
  type M80FixtureAdmission,
  type M80FoundationClassification,
  type M80HeldProfile,
  type M80SetupInput,
  type M80ValidatedSetup,
} from "./m80-contract"
import { createM80FixtureSetup, m80HashCanonical, M80_FIXTURE_SHA256 } from "./m80-fixture"
import { classifyM80Foundation, M80ValidationError, validateM80Setup } from "./m80-validation"
import { m71CanonicalJson } from "./m71-validation"

export const M80_RUNTIME_PROFILE = "m80-scope1-beta-foundation-runtime-v1" as const
export const M80_CORRECTION_REASON = "synthetic_fact_correction" as const

export interface M80BetaSetupVersion {
  id: string
  companyId: string
  reportingYear: 2025
  revision: number
  previousVersionId: string | null
  previousVersionSha256: string | null
  setup: M80ValidatedSetup
  payloadSha256: string
  versionSha256: string
  createdBy: string
  createdAt: string
}

export interface M80FoundationView {
  profile: typeof M80_RUNTIME_PROFILE
  syntheticOnly: true
  canManage: boolean
  fixtureAdmission: M80FixtureAdmission
  releaseRegistry: M80HeldProfile[]
  currentVersion: M80BetaSetupVersion | null
  history: M80BetaVersionSummary[]
  setup: M80ValidatedSetup
  eligibility: M80FoundationClassification
}

export interface M80SaveSetupInput {
  idempotencyKey: string
  expectedRevision: number
  expectedVersionId: string | null
  expectedVersionSha256: string | null
  correctionReason: null | typeof M80_CORRECTION_REASON
  setup: unknown
}

export interface M80SaveSetupResult {
  foundation: M80FoundationView
  savedVersion: M80BetaSetupVersion
  replayed: boolean
}

export type M80BetaVersionSummary = Omit<M80BetaSetupVersion, "setup">

interface AdmissionRow {
  company_id: string
  fixture_profile_id: typeof M80_FIXTURE_PROFILE
  fixture_version: number
  fixture_sha256: string
  active: boolean
}

interface ReleaseRow {
  profile_id: M80HeldProfile["profileId"]
  status: "held_candidate"
  method_id: string
  method_version: string | null
  method_sha256: string
  engine_sha256: string
  factor_identity_sha256: string
  gwp_identity_sha256: string
  source_artifact_ids: unknown
  reporting_period_start: string
  reporting_period_end_exclusive: string
  effective_at: string | null
  superseded_at: string | null
  exclusions: unknown
  decision_artifact_sha256: string
}

interface VersionRow {
  id: string
  company_id: string
  reporting_year: number
  revision: number
  previous_version_id: string | null
  previous_version_sha256: string | null
  fixture_profile_id: string
  fixture_version: number
  fixture_sha256: string
  payload: unknown
  canonical_payload: string
  payload_sha256: string
  version_sha256: string
  created_by: string
  created_at: string
  correction_reason: string | null
  data_classification: string
  completeness: string
  released_supported_count: number
  request_actor_id: string
  request_created_at: string
  request_sha256: string
  audit_actor_id: string
  audit_created_at: string
  audit_record_sha256: string
  audit_event_type: string
}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
const SHA256 = /^[0-9a-f]{64}$/

function exactObject(value: unknown, keys: string[], message = "Invalid M80 setup request."): asserts value is Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value) || Object.getPrototypeOf(value) !== Object.prototype || Object.keys(value).sort().join("|") !== [...keys].sort().join("|")) throw new M80ValidationError(message)
}

function releaseRegistry(rows: ReleaseRow[]): M80HeldProfile[] {
  return rows.map((row) => {
    if (!Array.isArray(row.source_artifact_ids) || row.source_artifact_ids.some((entry) => typeof entry !== "string") || row.reporting_period_start !== "2025-01-01" || row.reporting_period_end_exclusive !== "2026-01-01" || row.effective_at !== null || row.superseded_at !== null || row.decision_artifact_sha256 !== "848883159be48c88a0dab8589ad371dcdbbf8dd07966a3d5fbcfd0799f7a530b" || !Array.isArray(row.exclusions) || m80HashCanonical(row.exclusions) !== m80HashCanonical(["domain_release_pending", "rights_release_pending", "runtime_release_prohibited"])) throw new Error("M80 release registry could not be verified.")
    return {
      profileId: row.profile_id,
      status: row.status,
      methodId: row.method_id,
      methodVersion: row.method_version,
      methodSha256: row.method_sha256,
      engineSha256: row.engine_sha256,
      factorIdentitySha256: row.factor_identity_sha256,
      gwpIdentitySha256: row.gwp_identity_sha256,
      sourceArtifactIds: [...row.source_artifact_ids] as string[],
    }
  })
}

function admission(row: AdmissionRow): M80FixtureAdmission {
  if (row.fixture_profile_id !== M80_FIXTURE_PROFILE || row.fixture_version !== M80_FIXTURE_VERSION || row.fixture_sha256 !== M80_FIXTURE_SHA256 || row.active !== true) throw new Error("M80 fixture admission could not be verified.")
  return { companyId: row.company_id, fixtureProfileId: row.fixture_profile_id, fixtureVersion: M80_FIXTURE_VERSION, fixtureSha256: row.fixture_sha256, active: true }
}

function versionHashPayload(version: Omit<M80BetaSetupVersion, "versionSha256" | "setup"> & { fixtureProfileId: typeof M80_FIXTURE_PROFILE; fixtureVersion: typeof M80_FIXTURE_VERSION; fixtureSha256: string; dataClassification: typeof M80_DATA_CLASSIFICATION; completeness: "incomplete"; releasedSupportedCount: 0 }): Record<string, unknown> {
  return {
    profile: M80_RUNTIME_PROFILE,
    id: version.id,
    companyId: version.companyId,
    reportingYear: version.reportingYear,
    revision: version.revision,
    previousVersionId: version.previousVersionId,
    previousVersionSha256: version.previousVersionSha256,
    fixtureProfileId: version.fixtureProfileId,
    fixtureVersion: version.fixtureVersion,
    fixtureSha256: version.fixtureSha256,
    payloadSha256: version.payloadSha256,
    createdBy: version.createdBy,
    createdAt: version.createdAt,
    dataClassification: version.dataClassification,
    completeness: version.completeness,
    releasedSupportedCount: version.releasedSupportedCount,
  }
}

function persistedSetup(setup: M80ValidatedSetup): M80SetupInput {
  const { fixture: _fixture, sources, ...root } = setup
  return {
    ...root,
    sources: sources.map(({ sourceIdentitySha256: _identity, ...source }) => source),
  }
}

function decodeVersion(row: VersionRow, trustedAdmission: M80FixtureAdmission): M80BetaSetupVersion {
  if (m71CanonicalJson(row.payload) !== row.canonical_payload || m80HashCanonical(row.payload) !== row.payload_sha256) throw new Error("Stored M80 setup integrity check failed.")
  const setup = validateM80Setup(row.payload, trustedAdmission)
  const createdAt = new Date(row.created_at).toISOString()
  if (row.reporting_year !== 2025 || !Number.isSafeInteger(row.revision) || row.revision < 1 || row.fixture_profile_id !== M80_FIXTURE_PROFILE || row.fixture_version !== M80_FIXTURE_VERSION || row.fixture_sha256 !== trustedAdmission.fixtureSha256 || row.correction_reason !== (row.revision === 1 ? null : M80_CORRECTION_REASON) || row.data_classification !== M80_DATA_CLASSIFICATION || row.completeness !== "incomplete" || row.released_supported_count !== 0 || row.request_actor_id !== row.created_by || row.audit_actor_id !== row.created_by || new Date(row.request_created_at).toISOString() !== createdAt || new Date(row.audit_created_at).toISOString() !== createdAt || row.audit_record_sha256 !== row.version_sha256 || row.audit_event_type !== "setup_saved") throw new Error("Stored M80 setup integrity check failed.")
  const version: M80BetaSetupVersion = {
    id: row.id,
    companyId: row.company_id,
    reportingYear: 2025,
    revision: row.revision,
    previousVersionId: row.previous_version_id,
    previousVersionSha256: row.previous_version_sha256,
    setup,
    payloadSha256: row.payload_sha256,
    versionSha256: row.version_sha256,
    createdBy: row.created_by,
    createdAt,
  }
  const expected = m80HashCanonical(versionHashPayload({
    ...version,
    fixtureProfileId: row.fixture_profile_id,
    fixtureVersion: row.fixture_version,
    fixtureSha256: row.fixture_sha256,
    dataClassification: row.data_classification,
    completeness: row.completeness,
    releasedSupportedCount: row.released_supported_count,
  }))
  const expectedRequestSha256 = m80HashCanonical({
    operation: "save_scope1_beta_setup",
    actor: row.created_by,
    companyId: row.company_id,
    request: {
      profile: M80_RUNTIME_PROFILE,
      expectedRevision: row.revision - 1,
      expectedVersionId: row.previous_version_id,
      expectedVersionSha256: row.previous_version_sha256,
      correctionReason: row.revision === 1 ? null : M80_CORRECTION_REASON,
    },
    setup: row.payload,
  })
  if (expected !== version.versionSha256 || expectedRequestSha256 !== row.request_sha256) throw new Error("Stored M80 version integrity check failed.")
  return version
}

export function validateM80SaveSetup(value: unknown): M80SaveSetupInput {
  exactObject(value, ["idempotencyKey", "expectedRevision", "expectedVersionId", "expectedVersionSha256", "correctionReason", "setup"])
  if (typeof value.idempotencyKey !== "string" || !UUID.test(value.idempotencyKey) || !Number.isSafeInteger(value.expectedRevision) || (value.expectedRevision as number) < 0) throw new M80ValidationError("Invalid M80 setup request.")
  if (value.expectedRevision === 0) {
    if (value.expectedVersionId !== null || value.expectedVersionSha256 !== null || value.correctionReason !== null) throw new M80ValidationError("Exact initial M80 setup binding required.")
  } else if (typeof value.expectedVersionId !== "string" || !UUID.test(value.expectedVersionId) || typeof value.expectedVersionSha256 !== "string" || !SHA256.test(value.expectedVersionSha256) || value.correctionReason !== M80_CORRECTION_REASON) {
    throw new M80ValidationError("Exact M80 predecessor binding required.")
  }
  return value as unknown as M80SaveSetupInput
}

export async function readM80Foundation(tx: WorkspaceSql, companyId: string): Promise<M80FoundationView | null> {
  const admissions = await tx.query<AdmissionRow>(`select company_id,fixture_profile_id,fixture_version,fixture_sha256,active
    from neuvetra.scope1_beta_fixture_admissions where company_id=$1 and active`, [companyId])
  if (admissions.rows.length !== 1) return null
  const trustedAdmission = admission(admissions.rows[0]!)
  const releases = await tx.query<ReleaseRow>(`select profile_id,status,method_id,method_version,method_sha256,engine_sha256,
      factor_identity_sha256,gwp_identity_sha256,source_artifact_ids,reporting_period_start::text,reporting_period_end_exclusive::text,
      effective_at::text,superseded_at::text,exclusions,decision_artifact_sha256
    from neuvetra.scope1_beta_release_records order by profile_id`)
  const registry = releaseRegistry(releases.rows)
  const versions = await tx.query<VersionRow>(`select v.id,v.company_id,v.reporting_year,v.revision,v.previous_version_id,v.previous_version_sha256,
      v.fixture_profile_id,v.fixture_version,v.fixture_sha256,v.payload,v.canonical_payload,v.payload_sha256,v.version_sha256,v.created_by,v.created_at::text,
      v.correction_reason,v.data_classification,v.completeness,v.released_supported_count,
      r.actor_id request_actor_id,r.created_at::text request_created_at,r.request_sha256,a.actor_id audit_actor_id,a.created_at::text audit_created_at,
      a.record_sha256 audit_record_sha256,a.event_type audit_event_type
    from neuvetra.scope1_beta_setup_versions v
    join neuvetra.scope1_beta_requests r on r.company_id=v.company_id and r.record_id=v.id
    join neuvetra.scope1_beta_audit a on a.company_id=v.company_id and a.record_id=v.id
    where v.company_id=$1 and v.reporting_year=2025 order by v.revision`, [companyId])
  const decoded = versions.rows.map((row) => decodeVersion(row, trustedAdmission))
  for (let index = 0; index < decoded.length; index++) {
    const item = decoded[index]!
    const prior = decoded[index - 1] ?? null
    if (item.revision !== index + 1 || (item.previousVersionId !== (prior?.id ?? null)) || (item.previousVersionSha256 !== (prior?.versionSha256 ?? null))) throw new Error("M80 setup history integrity check failed.")
  }
  const heads = await tx.query<{ version_id: string; revision: number }>("select version_id,revision from neuvetra.scope1_beta_setup_heads where company_id=$1 and reporting_year=2025", [companyId])
  if (heads.rows.length > 1 || (decoded.length === 0) !== (heads.rows.length === 0)) throw new Error("M80 setup head could not be verified.")
  const currentVersion = decoded.length ? decoded[decoded.length - 1]! : null
  if (currentVersion && (heads.rows[0]?.version_id !== currentVersion.id || heads.rows[0]?.revision !== currentVersion.revision)) throw new Error("M80 setup head could not be verified.")
  const setup = currentVersion?.setup ?? validateM80Setup(createM80FixtureSetup(companyId), trustedAdmission)
  const rawSetup = currentVersion ? persistedSetup(currentVersion.setup) : createM80FixtureSetup(companyId)
  const eligibility = classifyM80Foundation(rawSetup, trustedAdmission, registry)
  const history = decoded.map(({ setup: _setup, ...summary }) => summary)
  const authority = await tx.query<{ allowed: boolean }>("select neuvetra.can_manage_company($1) allowed", [companyId])
  return { profile: M80_RUNTIME_PROFILE, syntheticOnly: true, canManage: authority.rows[0]?.allowed === true, fixtureAdmission: trustedAdmission, releaseRegistry: registry, currentVersion, history, setup, eligibility }
}

export async function readM80FoundationVersion(tx: WorkspaceSql, companyId: string, versionId: string): Promise<M80BetaSetupVersion | null> {
  if (!UUID.test(versionId)) return null
  const foundation = await readM80Foundation(tx, companyId)
  if (!foundation || !foundation.history.some((entry) => entry.id === versionId)) return null
  const admissions = await tx.query<AdmissionRow>(`select company_id,fixture_profile_id,fixture_version,fixture_sha256,active
    from neuvetra.scope1_beta_fixture_admissions where company_id=$1 and active`, [companyId])
  if (admissions.rows.length !== 1) return null
  const rows = await tx.query<VersionRow>(`select v.id,v.company_id,v.reporting_year,v.revision,v.previous_version_id,v.previous_version_sha256,
      v.fixture_profile_id,v.fixture_version,v.fixture_sha256,v.payload,v.canonical_payload,v.payload_sha256,v.version_sha256,v.created_by,v.created_at::text,
      v.correction_reason,v.data_classification,v.completeness,v.released_supported_count,
      r.actor_id request_actor_id,r.created_at::text request_created_at,r.request_sha256,a.actor_id audit_actor_id,a.created_at::text audit_created_at,
      a.record_sha256 audit_record_sha256,a.event_type audit_event_type
    from neuvetra.scope1_beta_setup_versions v
    join neuvetra.scope1_beta_requests r on r.company_id=v.company_id and r.record_id=v.id
    join neuvetra.scope1_beta_audit a on a.company_id=v.company_id and a.record_id=v.id
    where v.company_id=$1 and v.id=$2`, [companyId, versionId])
  return rows.rows.length === 1 ? decodeVersion(rows.rows[0]!, admission(admissions.rows[0]!)) : null
}

export async function saveM80Foundation(tx: WorkspaceSql, actorId: string, companyId: string, rawInput: unknown): Promise<M80SaveSetupResult> {
  const input = validateM80SaveSetup(rawInput)
  const admissions = await tx.query<AdmissionRow>(`select company_id,fixture_profile_id,fixture_version,fixture_sha256,active
    from neuvetra.scope1_beta_fixture_admissions where company_id=$1 and active`, [companyId])
  if (admissions.rows.length !== 1) throw Object.assign(new Error("M80 foundation not found."), { code: "M80_FOUNDATION_NOT_FOUND" })
  const trustedAdmission = admission(admissions.rows[0]!)
  const validatedSetup = validateM80Setup(input.setup, trustedAdmission)
  const setup = persistedSetup(validatedSetup)
  const payloadSha256 = m80HashCanonical(setup)
  const createdAt = new Date().toISOString()
  const id = crypto.randomUUID()
  const body = {
    profile: M80_RUNTIME_PROFILE,
    id,
    companyId,
    reportingYear: 2025 as const,
    revision: input.expectedRevision + 1,
    previousVersionId: input.expectedVersionId,
    previousVersionSha256: input.expectedVersionSha256,
    fixtureProfileId: M80_FIXTURE_PROFILE,
    fixtureVersion: M80_FIXTURE_VERSION,
    fixtureSha256: M80_FIXTURE_SHA256,
    payloadSha256,
    createdBy: actorId,
    createdAt,
    dataClassification: M80_DATA_CLASSIFICATION,
    completeness: "incomplete" as const,
    releasedSupportedCount: 0 as const,
  }
  const version = { ...body, versionSha256: m80HashCanonical(body) }
  const request = {
    profile: M80_RUNTIME_PROFILE,
    idempotencyKey: input.idempotencyKey,
    expectedRevision: input.expectedRevision,
    expectedVersionId: input.expectedVersionId,
    expectedVersionSha256: input.expectedVersionSha256,
    correctionReason: input.correctionReason,
  }
  const saved = await tx.query<{ record_id: string; replayed: boolean }>("select * from neuvetra.save_scope1_beta_setup($1,$2::text::jsonb,$3::text::jsonb,$4::text::jsonb)", [companyId, JSON.stringify(request), JSON.stringify(setup), JSON.stringify(version)])
  if (saved.rows.length !== 1) throw new Error("M80 setup write could not be verified.")
  const foundation = await readM80Foundation(tx, companyId)
  const savedVersion = await readM80FoundationVersion(tx, companyId, saved.rows[0]!.record_id)
  if (!foundation || !savedVersion) throw new Error("M80 setup write could not be read back.")
  return { foundation, savedVersion, replayed: saved.rows[0]!.replayed }
}

import type { WorkspaceConnection, WorkspaceSql } from "./workspace"
import { auditLegacyStagingExposure, EXISTING_PROJECT_REF } from "./staging-audit"

export const STAGING_MIGRATIONS = [
  "0001_company_workspace.sql", "0002_synthetic_bill_intake.sql", "0003_synthetic_bill_calculation.sql",
  "0004_inventory_review.sql", "0005_annual_electricity_register.sql", "0006_inventory_evidence_pack.sql",
  "0007_inventory_draft_report.sql", "0008_inventory_draft_report_review.sql", "0009_private_staging.sql", "0010_manual_electricity_worksheet.sql", "0011_worksheet_reports.sql", "0012_source_electricity_worksheet.sql", "0013_annual_electricity_worksheet.sql", "0014_annual_electricity_evidence.sql",
  "0015_corporate_coverage.sql",
  "0016_stationary_natural_gas.sql",
  "0017_mobile_diesel.sql",
  "0018_controlled_fleet.sql",
  "0019_stationary_sources.sql",
  "0020_fugitive_sources.sql",
  "0021_scope1_inventory.sql",
  "0022_scope1_beta_foundation.sql",
] as const

export async function readMigrationManifest() {
  return Promise.all(STAGING_MIGRATIONS.map(async name => {
    const sql = await Bun.file(new URL(`./migrations/${name}`, import.meta.url)).text()
    // Normalize checkout newline differences, preserving every SQL token.
    const canonical = sql.replace(/\r\n/g, "\n")
    return { name, sha256: new Bun.CryptoHasher("sha256").update(canonical).digest("hex"), sql: canonical }
  }))
}

async function validateExisting(tx: WorkspaceSql, expectedProjectRef: string, manifest: Awaited<ReturnType<typeof readMigrationManifest>>) {
  const receipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra.schema_migrations order by name")
  const target = await tx.query<{ project_ref: string; profile: string }>("select project_ref,profile from neuvetra.staging_target")
  if (target.rows.length !== 1 || target.rows[0]?.project_ref !== expectedProjectRef || target.rows[0]?.profile !== "neuvetra.private-synthetic-staging.v1" || receipts.rows.length !== manifest.length || receipts.rows.some((r, i) => r.name !== manifest[i]?.name || r.sha256 !== manifest[i]?.sha256)) throw new Error("Unknown or changed staging migration baseline.")
}

/** Explicit operator call. Requires a reviewed synthetic target; never called by HTTP startup. */
export async function migratePrivateStaging(db: WorkspaceConnection, approval: { expectedProjectRef: string; syntheticTargetConfirmed: true; reuseExistingProject?: boolean }) {
  if (approval.syntheticTargetConfirmed !== true || !/^[a-z]{20}$/.test(approval.expectedProjectRef)) throw new Error("Reviewed synthetic staging target required.")
  if (approval.expectedProjectRef === EXISTING_PROJECT_REF && (approval.reuseExistingProject !== true || !(await auditLegacyStagingExposure(db)).legacyContainmentVerified)) throw new Error("Confirmed existing project reuse and verified legacy containment required.")
  const manifest = await readMigrationManifest()
  await db.transaction(async tx => {
    await tx.query("select pg_advisory_xact_lock(630009)")
    const existing = await tx.query<{ present: boolean }>("select exists(select 1 from pg_namespace where nspname='neuvetra') present")
    if (existing.rows[0]?.present) {
      const receipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra.schema_migrations order by name")
      if (receipts.rows.length !== 9 && receipts.rows.length !== 10 && receipts.rows.length !== 11 && receipts.rows.length !== 12 && receipts.rows.length !== 13 && receipts.rows.length !== 14 && receipts.rows.length !== 15 && receipts.rows.length !== 16 && receipts.rows.length !== 17 && receipts.rows.length !== 18 && receipts.rows.length !== 19 && receipts.rows.length !== 20 && receipts.rows.length !== 21 && receipts.rows.length !== manifest.length) throw new Error("Unknown staging migration baseline.")
      await validateExisting(tx, approval.expectedProjectRef, manifest.slice(0,receipts.rows.length))
      for (const migration of manifest.slice(receipts.rows.length)) {
        await tx.exec(migration.sql)
        await tx.query("insert into neuvetra.schema_migrations(name,sha256) values($1,$2)",[migration.name,migration.sha256])
      }
      return
    }
    // Supabase must provide real Auth; no fake users, auth function or role creation here.
    await tx.query("select auth.uid()")
    const auth = await tx.query<{ present: boolean }>("select to_regclass('auth.users') is not null and exists(select 1 from pg_roles where rolname='authenticated') present")
    if (!auth.rows[0]?.present) throw new Error("Real Auth baseline required.")
    for (const migration of manifest) await tx.exec(migration.sql)
    await tx.exec(`create table neuvetra.schema_migrations(name text primary key,sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$'),applied_at timestamptz not null default now());
      create table neuvetra.staging_target(singleton boolean primary key default true check(singleton),project_ref text not null,profile text not null);
      alter table neuvetra.schema_migrations enable row level security; alter table neuvetra.schema_migrations force row level security;
      alter table neuvetra.staging_target enable row level security; alter table neuvetra.staging_target force row level security;
      create policy m63_receipts_read on neuvetra.schema_migrations for select to neuvetra_runtime using(true);
      create policy m63_target_read on neuvetra.staging_target for select to neuvetra_runtime using(true);
      grant select on neuvetra.schema_migrations,neuvetra.staging_target to neuvetra_runtime;`)
    for (const migration of manifest) await tx.query("insert into neuvetra.schema_migrations(name,sha256) values($1,$2)", [migration.name, migration.sha256])
    await tx.query("insert into neuvetra.staging_target(project_ref,profile) values($1,'neuvetra.private-synthetic-staging.v1')", [approval.expectedProjectRef])
  })
  return { schemaVersion: manifest.length, migrations: manifest.map(({ name, sha256 }) => ({ name, sha256 })) }
}

export interface ApprovedStagingRoster {
  expectedProjectRef: string
  workspaceId: string
  ownerUserId: string
  members: ReadonlyArray<{ userId: string; role: "admin" | "member" }>
}

/** Trusted operator-only provisioning of explicitly approved existing real Auth UUIDs. */
export async function provisionStagingRoster(db: WorkspaceConnection, roster: ApprovedStagingRoster): Promise<{ workspaceId: string }> {
  const ids = [roster.ownerUserId, ...roster.members.map(m => m.userId)]
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
  if (!uuid.test(roster.workspaceId) || ids.some(id => !uuid.test(id)) || new Set(ids).size !== ids.length || roster.members.some(m => !["admin", "member"].includes(m.role))) throw new Error("Explicit distinct approved Auth subjects required.")
  const manifest = await readMigrationManifest()
  await db.transaction(async tx => {
    await tx.query("select pg_advisory_xact_lock(630009)")
    await validateExisting(tx, roster.expectedProjectRef, manifest)
    for (const id of ids) {
      const subject = await tx.query<{ id: string }>("select id from auth.users where id=$1", [id])
      if (subject.rows.length !== 1) throw new Error("Approved subject does not exist in target Auth.")
      const previous = await tx.query<{ company_id: string | null }>("select company_id from neuvetra.staging_access where user_id=$1", [id])
      if (previous.rows.length && previous.rows[0]?.company_id !== roster.workspaceId) throw new Error("Subject already belongs to another staging roster.")
    }
    const existing = await tx.query<{ created_by: string }>("select created_by from neuvetra.companies where id=$1", [roster.workspaceId])
    if (existing.rows.length && existing.rows[0]?.created_by !== roster.ownerUserId) throw new Error("Staging workspace owner mismatch.")
    if (!existing.rows.length) {
      await tx.query("insert into neuvetra.staging_access(user_id,active) values($1,true)", [roster.ownerUserId])
      await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [roster.ownerUserId])
      await tx.query("select neuvetra.create_company_workspace($1,'Synthetic Acme, Inc.',$2,'Synthetic California office',$3,2023,$4)", [roster.workspaceId, crypto.randomUUID(), crypto.randomUUID(), crypto.randomUUID()])
    }
    // Exact replacement revokes absent users for this workspace; no stale JWT override.
    await tx.query("update neuvetra.staging_access set active=false where company_id=$1", [roster.workspaceId])
    for (const member of [{ userId: roster.ownerUserId, role: "owner" }, ...roster.members]) {
      await tx.query("insert into neuvetra.company_members(company_id,user_id,role) values($1,$2,$3) on conflict(company_id,user_id) do update set role=excluded.role", [roster.workspaceId, member.userId, member.role])
      await tx.query("insert into neuvetra.staging_access(user_id,company_id,active) values($1,$2,true) on conflict(user_id) do update set company_id=excluded.company_id,active=true,approved_at=now()", [member.userId, roster.workspaceId])
    }
  })
  return { workspaceId: roster.workspaceId }
}

/** Explicit revocation is independent of Auth JWT lifetime and preserves domain history. */
export async function revokeStagingAccess(db: WorkspaceConnection, userId: string): Promise<void> {
  await db.query("update neuvetra.staging_access set active=false where user_id=$1", [userId])
}

import postgres from "postgres"
import { validateDatabaseCaPem } from "./staging-tls"
import { WorkspaceDatabase, type WorkspaceConnection, type WorkspaceSql, type CompanyWorkspaceRecord, type SyntheticWorkspaceInput } from "./workspace"
import { auditLegacyStagingExposure, EXISTING_PROJECT_REF } from "./staging-audit"
import { readMigrationManifest } from "./staging-migrations"

export const STAGING_PROFILE = "neuvetra.private-synthetic-staging.v1" as const
export const STAGING_SCHEMA_VERSION = 22
export interface HostedWorkspaceOptions {
  connectionString: string
  expectedProjectRef: string
  maxConnections?: number
  reuseExistingProject?: boolean
  tlsCaPem?: string
}

/** Parameterized SQL only. No user input may supply SQL text or verified identity. */
function wrapSql(sql: Pick<postgres.Sql, "unsafe">): WorkspaceSql {
  return {
    async query<T>(statement: string, params: unknown[] = []) {
      // bytea uses an explicit Buffer; JSON and numeric text stay untouched.
      const rows = await sql.unsafe<T[]>(statement, params.map(value => value instanceof Uint8Array ? Buffer.from(value) : value) as postgres.ParameterOrJSON<never>[])
      return { rows: Array.from(rows) }
    },
    async exec(statement: string) { await sql.unsafe(statement).simple() },
  }
}

/** Low-level driver shared with explicit operator tooling; never migrates. */
export function createPostgresConnection(connectionString: string, options: { maxConnections?: number; tls?: boolean; tlsCaPem?:string } = {}): WorkspaceConnection {
  const ca = options.tlsCaPem === undefined ? undefined : validateDatabaseCaPem(options.tlsCaPem)
  if(options.tls===false && ca!==undefined) throw new Error("A database CA requires verified TLS.")
  const sql = postgres(connectionString, {
    max: options.maxConnections ?? 4,
    ssl: options.tls === false ? false : { rejectUnauthorized: true, ...(ca===undefined ? {} : {ca}) },
    connect_timeout: 10, idle_timeout: 30, max_lifetime: 300,
    prepare: false,
    onnotice: () => {},
    connection: { application_name: "neuvetra-m63", statement_timeout: 15000, lock_timeout: 5000, idle_in_transaction_session_timeout: 30000, timezone: "UTC" },
  })
  return {
    ...wrapSql(sql),
    async transaction<T>(operation: (tx: WorkspaceSql) => Promise<T>): Promise<T> {
      return await sql.begin(async (tx) => operation(wrapSql(tx))) as T
    },
    async close() { await sql.end({ timeout: 5 }) },
  }
}

export function validateHostedTarget(options: HostedWorkspaceOptions): void {
  let url: URL
  try { url = new URL(options.connectionString) } catch { throw new Error("Invalid staging database target.") }
  const ref = options.expectedProjectRef
  if (ref === EXISTING_PROJECT_REF && options.reuseExistingProject !== true) throw new Error("Explicit existing project reuse confirmation required.")
  const user = decodeURIComponent(url.username)
  const direct = url.hostname === `db.${ref}.supabase.co` && user === "neuvetra_runtime" && (!url.port || url.port === "5432")
  const pooled = /^aws-[0-9]+-[a-z0-9-]+\.pooler\.supabase\.com$/.test(url.hostname) && user === `neuvetra_runtime.${ref}` && (url.port === "5432" || url.port === "6543")
  if (!/^[a-z]{20}$/.test(ref) || !["postgres:", "postgresql:"].includes(url.protocol) || (!direct && !pooled) || !url.password || url.pathname !== "/postgres" || url.search || url.hash || (options.maxConnections !== undefined && (!Number.isInteger(options.maxConnections) || options.maxConnections < 1 || options.maxConnections > 8))) {
    throw new Error("Staging database target must match the isolated Auth project and dedicated runtime login.")
  }
}

function requireSubject(userId: string) {
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(userId)) throw new Error("Verified authentication subject required.")
}

export class HostedWorkspaceDatabase extends WorkspaceDatabase {
  private constructor(db: WorkspaceConnection, private readonly expectedProjectRef: string, private readonly reuseExistingProject = false) { super(db) }

  static async create(options: HostedWorkspaceOptions): Promise<HostedWorkspaceDatabase> {
    validateHostedTarget(options)
    const db = createPostgresConnection(options.connectionString, { maxConnections: options.maxConnections, tlsCaPem:options.tlsCaPem })
    const workspace = new HostedWorkspaceDatabase(db, options.expectedProjectRef, options.reuseExistingProject)
    try { await workspace.checkReadiness(); return workspace } catch { await db.close(); throw new Error("Staging database readiness validation failed.") }
  }

  async checkReadiness(): Promise<{ profile: typeof STAGING_PROFILE; schemaVersion: number; legacyContainmentVerified?: true }> {
    if (this.expectedProjectRef === EXISTING_PROJECT_REF) {
      if (!this.reuseExistingProject || !(await auditLegacyStagingExposure(this.db)).legacyContainmentVerified) throw new Error("Legacy project containment is not verified.")
    }
    const manifest = await readMigrationManifest()
    await this.db.transaction(async tx => {
      const role = await tx.query<{ safe: boolean }>(`select
        current_user='neuvetra_runtime' and session_user='neuvetra_runtime'
        and not r.rolsuper and not r.rolbypassrls and not r.rolcreatedb and not r.rolcreaterole and not r.rolreplication and not r.rolinherit
        and not exists(select 1 from pg_auth_members where member=r.oid)
        and not exists(select 1 from pg_namespace where nspname='neuvetra' and nspowner=r.oid)
        and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='neuvetra' and p.proowner=r.oid)
        and not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and (c.relowner=r.oid or (c.relkind='r' and (not c.relrowsecurity or not c.relforcerowsecurity))))
        and not has_schema_privilege(current_user,'neuvetra','CREATE')
        and not has_schema_privilege(current_user,'public','CREATE')
        and not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='neuvetra' and c.relkind in('r','p','v','m','f') and has_table_privilege(current_user,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))
        as safe from pg_roles r where r.rolname=current_user`)
      if (role.rows[0]?.safe !== true) throw new Error("Unsafe staging runtime role.")
      const metadata = await tx.query<{ project_ref: string; profile: string }>("select project_ref,profile from neuvetra.staging_target")
      if (metadata.rows.length !== 1 || metadata.rows[0]?.project_ref !== this.expectedProjectRef || metadata.rows[0]?.profile !== STAGING_PROFILE) throw new Error("Staging target mismatch.")
      const receipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra.schema_migrations order by name")
      if (receipts.rows.length !== manifest.length || receipts.rows.some((r, i) => r.name !== manifest[i]?.name || r.sha256 !== manifest[i]?.sha256)) throw new Error("Staging schema receipt mismatch.")
    })
    return { profile: STAGING_PROFILE, schemaVersion: STAGING_SCHEMA_VERSION, ...(this.expectedProjectRef === EXISTING_PROJECT_REF ? {legacyContainmentVerified:true as const} : {}) }
  }

  protected override async asUser<T>(userId: string, operation: (tx: WorkspaceSql) => Promise<T>): Promise<T> {
    requireSubject(userId)
    return this.db.transaction(async tx => {
      await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [userId])
      const access = await tx.query<{ allowed: boolean }>("select neuvetra.has_staging_access() allowed")
      if (access.rows[0]?.allowed !== true) throw new Error("Private staging access required.")
      return operation(tx)
    })
  }

  protected override asTrustedUser<T>(userId: string, operation: (tx: WorkspaceSql) => Promise<T>): Promise<T> {
    // Hosted writes use the same non-owner role and per-transaction gate as reads.
    return this.asUser(userId, operation)
  }

  async hasStagingAccess(userId: string): Promise<boolean> {
    requireSubject(userId)
    return this.db.transaction(async tx => {
      await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [userId])
      return (await tx.query<{ allowed: boolean }>("select neuvetra.has_staging_access() allowed")).rows[0]?.allowed === true
    })
  }

  async findStagingWorkspaceForUser(userId: string): Promise<{ workspace: CompanyWorkspaceRecord; role: "owner" | "admin" | "member"; evidenceId: string | null } | null> {
    const result = await this.asUser(userId, async tx => {
      const memberships = await tx.query<{ company_id: string; role: "owner" | "admin" | "member" }>("select company_id,role from neuvetra.company_members where user_id=$1", [userId])
      if (memberships.rows.length !== 1) return null
      const member = memberships.rows[0]!
      const evidence = await tx.query<{ id: string }>("select id from neuvetra.bill_evidence where company_id=$1 order by created_at,id limit 1", [member.company_id])
      return { ...member, evidenceId: evidence.rows[0]?.id ?? null }
    })
    if (!result) return null
    const workspace = await this.findWorkspace(userId, result.company_id)
    return workspace ? { workspace, role: result.role, evidenceId: result.evidenceId } : null
  }

  override async createWorkspace(userId: string, _input: SyntheticWorkspaceInput): Promise<CompanyWorkspaceRecord> {
    const current = await this.findStagingWorkspaceForUser(userId)
    if (!current || current.role === "member") throw new Error("Approved staging workspace required.")
    return current.workspace
  }

  override async createWorkspaceWithSyntheticMembers(): Promise<CompanyWorkspaceRecord> {
    throw new Error("Staging memberships require explicit operator provisioning.")
  }
}

